er", "type": "DataProperty", "domain": "InvoiceHeaderSection", "range": "xsd:string"}, {"name": "hasInvoiceNumber", "type": "DataProperty", "domain": "InvoiceHeaderSection", "range": "xsd:string"}, {"name": "hasDate", "type": "DataProperty", "domain": "InvoiceHeaderSection", "range": "xsd:string"}, {"name": "hasItem", "type": "ObjectProperty", "domain": "LineItem", "range": "Item"}, {"name": "hasNetPrice", "type": "ObjectProperty", "domain": "LineItem", "range": "Price"}, {"name": "hasQuantity", "type": "ObjectProperty", "domain": "LineItem", "range": "Quantity"}, {"name": "hasTax", "type": "ObjectProperty", "domain": "InvoiceSummarySection", "range": "Tax"}, {"name": "hasInvoiceAmount", "type": "DataProperty", "domain": "InvoiceSummarySection", "range": "xsd:decimal"}, {"name": "hasTotalTaxAmount", "type": "DataProperty", "domain": "InvoiceSummarySection", "range": "xsd:decimal"}, {"name": "hasBusinessProcess", "type": "ObjectProperty", "domain": "InvoiceMessage", "range": "BusinessProcess"}, {"name": "isAlignedWithStandard", "type": "ObjectProperty", "domain": "InvoiceMessage", "range": "Standard"}, {"name": "validatedBy", "type": "ObjectProperty", "domain": "InvoiceMessage", "range": "SHACLConstraint"}, {"name": "hasMandatoryIdentifier", "type": "ObjectProperty", "domain": "EDIFACTDirectory", "range": "Identifier"}]}, "cq_coverage": {"1": "EDIFACTMessage (or InvoiceMessage) is composed of InvoiceMessage instances via containsMessage and hasSection; invoices are InvoiceMessage instances contained in an EDIFACTMessage.", "2": "Organizations involved are linked via hasOrganization (InvoiceMessage->Organization), and more specifically via RoleAssignment and involvesOrganization.", "3": "RoleAssignment (pivot class) links an Organization to its AgentRole within an InvoiceMessage (via hasRoleAssignment, involvesOrganization, hasAgentRole).", "4": "RoleAssignment with hasAgentRole=Buyer identifies the buyer organization for a given invoice.", "5": "Organization is linke